    /** One path of an icon: its SVG `d`, whether the source fills it even-odd, or the width it strokes it at. */
    private class P(val d: String, val evenOdd: Boolean = false, val stroke: Float? = null)

    private const val GUIDE_STROKE = 1.75f
    private const val ICON_STROKE = 1.75f

    private fun icon(name: String, vararg paths: P): ImageVector =
        ImageVector.Builder(
            name = name,
            defaultWidth = TouchpointMetrics.iconDefaultSize,
            defaultHeight = TouchpointMetrics.iconDefaultSize,
            viewportWidth = TouchpointMetrics.ICON_GRID,
            viewportHeight = TouchpointMetrics.ICON_GRID,
        ).apply {
            for (p in paths) {
                addPath(
                    pathData = PathParser().parsePathString(p.d).toNodes(),
                    pathFillType = if (p.evenOdd) PathFillType.EvenOdd else PathFillType.NonZero,
                    fill = if (p.stroke == null) SolidColor(Color.Black) else null,
                    stroke = p.stroke?.let { SolidColor(Color.Black) },
                    strokeLineWidth = p.stroke ?: 0f,
                    strokeLineCap = androidx.compose.ui.graphics.StrokeCap.Round,
                    strokeLineJoin = androidx.compose.ui.graphics.StrokeJoin.Round,
                )
            }
        }.build()
}

/**
 * A built-in icon a host can replace, through [TouchpointChatOptions.icons]: web's `icons` option,
 * keyed by the names of web's `Icons` (`Close`, `Send`, `Mic`…), plus the few Android draws that web
 * has none of.
 */
public enum class TouchpointIcon {
    /** web's `Restart`. */
    RESTART,
    /** web's `Settings`. */
    SETTINGS,
    /** web's `Close`. */
    CLOSE,
    /** web's `ArrowLeft`. */
    ARROW_LEFT,
    /** web's `Send`. */
    SEND,
    /** web's `Attachment`. */
    ATTACHMENT,
    /** web's `Undo`. */
    UNDO,
    /** web's `Download`. */
    DOWNLOAD,
    /** web's `LogOut`. */
    LOG_OUT,
    /** web's `Warning`. */
    WARNING,
    /** web's `Time`. */
    TIME,
    /** web's `Check`. */
    CHECK,
    /** web's `CheckDouble`. */
    CHECK_DOUBLE,
    /** web's `Error`. */
    ERROR,
    /** web's `Delete`. */
    DELETE,
    /** web's `ArrowUp`. */
    ARROW_UP,
    /** web's `Minimize`. */
    MINIMIZE,
    /** Android's own; web has none. */
    SCREEN_SHARE,
    /** web's `Date`. */
    DATE,
    /** web's `ArrowForward`. */
    ARROW_FORWARD,
    /** web's `Play`. */
    PLAY,
    /** web's `Guide`. */
    GUIDE,
    /** web's `Reorder`. */
    REORDER,
    /** Android's own; web has none. */
    CHAT,
    /** Android's own; web has none. */
    MENU,
    /** web's `Mic`. */
    MIC,
    /** web's `MicOff`. */
    MIC_OFF,
    /** web's `Volume`. */
    VOLUME,
    /** web's `VolumeOff`. */
    VOLUME_OFF,
    /** web's `Touchpoint`. */
    TOUCHPOINT,
    /** web's `Escalate`. */
    ESCALATE,
    /** web's `Bot`. */
    BOT,
    /** web's `User`. */
    USER,
    /** The design guide's assistant sparkle: the header's brand and the assistant's avatar. */
    SPARKLE,
    /** Android's own; web has none: Call us, in the settings. */
    PHONE,
}

/**
 * The icons as drawn: each the host's replacement where [TouchpointChatOptions.icons] has one, else
 * Touchpoint web's own ([DefaultIcons]). Read in composition, so a replacement applies everywhere
 * the SDK draws that icon, as web's does.
 */
@InternalTouchpointUi
public object TouchpointIcons {
    public val Restart: ImageVector @Composable get() = pick(TouchpointIcon.RESTART, DefaultIcons.Restart)
    public val Settings: ImageVector @Composable get() = pick(TouchpointIcon.SETTINGS, DefaultIcons.Settings)
    public val Close: ImageVector @Composable get() = pick(TouchpointIcon.CLOSE, DefaultIcons.Close)
    public val Back: ImageVector @Composable get() = pick(TouchpointIcon.ARROW_LEFT, DefaultIcons.Back)
    public val Send: ImageVector @Composable get() = pick(TouchpointIcon.SEND, DefaultIcons.Send)
    public val Attach: ImageVector @Composable get() = pick(TouchpointIcon.ATTACHMENT, DefaultIcons.Attach)
